import { loadFont as loadUbuntu } from "@remotion/google-fonts/Ubuntu";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, spring, staticFile, useCurrentFrame } from "remotion";

// MULT PROFISSÕES (Anápolis) · matrículas do Curso Completo de Informática Administrativa, parcelas de R$ 99,90.
// Vídeo de 37 s com imagens reais das aulas (vídeos do cliente) intercaladas com cenas desenhadas na identidade do logo:
// laranja "MULT", verde "Profissões", flor de lótus colorida, fonte Ubuntu (a do logo). Fundo branco como as paredes da escola.
// Tela final pedida pelo cliente: fixo (00) 00000-0000 e WhatsApp (00) 00000-0000, grandes e organizados.
// Tempos = palavra na voz ((arquivo do cliente)), voz o locutor, entra em LEAD.

const { fontFamily: F } = loadUbuntu("normal", { weights: ["400", "500", "700"], subsets: ["latin", "latin-ext"] });

export const MF_FPS = 30;
const LEAD = 0.1;
export const MF_FRAMES = Math.round(37 * MF_FPS);

const ORANGE = "#EE6F12";
const AMBER = "#F7A21B";
const GREEN = "#4E9A1C";
const DEEPG = "#2F6B0E";
const RED = "#E0261B";
const INK = "#2A2320";
const WHITE = "#FFFFFF";
const PAPER = "#FBF8F4";
const WA = "#25D366";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const sp = (t: number, a: number, damping = 14, stiffness = 180) =>
  spring({ frame: Math.round((t - a) * MF_FPS), fps: MF_FPS, config: { damping, stiffness } });

// ───────── texto ─────────
type W = [string, number];
const Words: React.FC<{ t: number; words: W[]; size?: number; color?: string; weight?: number; shadow?: boolean }> = ({ t, words, size = 60, color = WHITE, weight = 500, shadow }) => (
  <div style={{ fontFamily: F, fontWeight: weight, fontSize: size, lineHeight: 1.15, color, textAlign: "center", whiteSpace: "nowrap", textShadow: shadow ? "0 4px 24px rgba(0,0,0,0.7)" : undefined }}>
    {words.map(([w, at], i) => {
      const q = k(t, at, 0.24);
      return <span key={i} style={{ display: "inline-block", margin: "0 0.12em", opacity: q, transform: `scale(${0.6 + 0.4 * q})`, filter: `blur(${(1 - q) * 6}px)` }}>{w}</span>;
    })}
  </div>
);
// destaque: carimba (vem grande e assenta)
const Big: React.FC<{ t: number; at: number; children: React.ReactNode; size?: number; color?: string; shadow?: boolean }> = ({ t, at, children, size = 120, color = WHITE, shadow }) => {
  const s = sp(t, at, 12, 220);
  return (
    <div style={{ fontFamily: F, fontWeight: 700, fontSize: size, lineHeight: 1.02, letterSpacing: "-0.02em", textAlign: "center", whiteSpace: "nowrap", color,
      opacity: Math.min(1, s * 3), transform: `scale(${1.6 - 0.6 * s})`, textShadow: shadow ? "0 6px 30px rgba(0,0,0,0.65)" : undefined }}>{children}</div>
  );
};
// faixa colorida atrás da palavra (como a faixa da parede da escola)
const Tag: React.FC<{ t: number; at: number; children: React.ReactNode; bg?: string; color?: string; size?: number; rot?: number }> = ({ t, at, children, bg = ORANGE, color = WHITE, size = 96, rot = -2 }) => {
  const s = sp(t, at, 12, 230);
  return (
    <div style={{ padding: "14px 44px 20px", borderRadius: 24, background: bg, boxShadow: "0 20px 50px rgba(0,0,0,0.35)", fontFamily: F, fontWeight: 700, fontSize: size, lineHeight: 1, color, whiteSpace: "nowrap",
      opacity: Math.min(1, s * 3), transform: `scale(${0.4 + 0.6 * s}) rotate(${(1 - s) * 8 + rot}deg)` }}>{children}</div>
  );
};
const Block: React.FC<{ t: number; top: number; at: number; out?: number; gap?: number; children: React.ReactNode }> = ({ t, top, at, out, gap = 10, children }) => {
  if (t < at - 0.05 || (out !== undefined && t > out + 0.14)) return null;
  const o = out === undefined ? 0 : k(t, out, 0.12);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap, opacity: 1 - o, transform: `scale(${1 - o * 0.08})` }}>{children}</div>
  );
};

// ───────── fundos, vídeos, transições ─────────
const Paper: React.FC = () => <AbsoluteFill style={{ background: `radial-gradient(ellipse 85% 60% at 50% 45%, #FFFFFF 0%, ${PAPER} 60%, #F1EAE0 100%)` }} />;
const Orange: React.FC = () => <AbsoluteFill style={{ background: `radial-gradient(ellipse 85% 60% at 50% 45%, #F7891F 0%, ${ORANGE} 55%, #C9520A 100%)` }} />;
const Green: React.FC = () => <AbsoluteFill style={{ background: `radial-gradient(ellipse 85% 60% at 50% 45%, #5FAE26 0%, ${GREEN} 55%, ${DEEPG} 100%)` }} />;

// trecho de vídeo do cliente: começa em `from` (s do arquivo) quando a cena chega em `a`
const Clip: React.FC<{ t: number; src: string; a: number; b: number; from: number; z0?: number; z1?: number; ox?: number; oy?: number; pos?: string }> = ({ t, src, a, b, from, z0 = 1.08, z1 = 1.2, ox = 50, oy = 50, pos = "50% 50%" }) => {
  const e = 0.3 * k(t, a, 0.6) + 0.7 * lin(t, a, b);
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: INK }}>
      <Sequence from={Math.round((a + LEAD) * MF_FPS)} durationInFrames={Math.round((b - a + 0.6) * MF_FPS)}>
        <AbsoluteFill style={{ transform: `scale(${(z0 + (z1 - z0) * e).toFixed(4)})`, transformOrigin: `${ox}% ${oy}%` }}>
          <OffthreadVideo src={staticFile(`multifuncoes/${src}.mp4`)} muted startFrom={Math.round(from * MF_FPS)}
            style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, filter: "contrast(1.08) saturate(1.18) brightness(1.04)" }} />
        </AbsoluteFill>
      </Sequence>
    </AbsoluteFill>
  );
};
const Scrim: React.FC<{ top?: boolean; mid?: boolean }> = ({ top, mid }) => (
  <AbsoluteFill style={{ background: mid
    ? "radial-gradient(ellipse 90% 40% at 50% 50%, rgba(20,12,6,0.62) 0%, rgba(20,12,6,0.25) 70%, rgba(20,12,6,0.15) 100%)"
    : top
    ? "linear-gradient(180deg, rgba(20,12,6,0.88) 0%, rgba(20,12,6,0.5) 26%, rgba(20,12,6,0) 46%)"
    : "linear-gradient(180deg, rgba(20,12,6,0) 46%, rgba(20,12,6,0.6) 68%, rgba(20,12,6,0.9) 100%)" }} />
);

type Tr = "none" | "cut" | "band" | "slideL" | "slideUp" | "zoom" | "circle" | "iris" | "flip" | "wipe";
const TD = 0.4;
const Scene: React.FC<{ t: number; a: number; b: number; tr: Tr; cam?: [number, number]; drift?: number; children: React.ReactNode }> = ({ t, a, b, tr, cam = [1, 1.06], drift = -40, children }) => {
  if (t < a || t > b + TD) return null;
  const q = tr === "none" || tr === "cut" ? 1 : k(t, a, TD);
  let clip = "none", tf = "", op = 1;
  if (tr === "band") clip = `polygon(0 ${(1 - q) * 100}%, 100% ${(1 - q) * 100 - 20 * (1 - q)}%, 100% 100%, 0 100%)`;
  if (tr === "wipe") clip = `polygon(0 0, ${q * 125}% 0, ${q * 125 - 25}% 100%, 0 100%)`;
  if (tr === "slideL") tf = `translateX(${(1 - q) * 100}%)`;
  if (tr === "slideUp") tf = `translateY(${(1 - q) * 100}%)`;
  if (tr === "zoom") { tf = `scale(${1.3 - 0.3 * q})`; op = Math.min(1, q * 1.7); }
  if (tr === "circle") clip = `circle(${q * 120}% at 50% 50%)`;
  if (tr === "iris") clip = `inset(${(1 - q) * 50}% ${(1 - q) * 50}% round ${(1 - q) * 200}px)`;
  if (tr === "flip") { tf = `perspective(2200px) rotateX(${(1 - q) * -80}deg)`; op = q > 0.02 ? 1 : 0; }
  const p = lin(t, a, b + TD);
  // nunca deixa borda aparecer: a escala cobre o deslocamento vertical
  const z = Math.max(cam[0] + (cam[1] - cam[0]) * p, 1.006 + (Math.abs(drift * p) * 2) / 1920);
  return (
    <AbsoluteFill style={{ clipPath: clip, transform: tf || undefined, opacity: op, overflow: "hidden" }}>
      <AbsoluteFill style={{ transform: `translateY(${(drift * p).toFixed(1)}px) scale(${z.toFixed(4)})` }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};
// clarão curto nos cortes secos da abertura
const Flash: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const f = t >= at && t < at + 0.2 ? 1 - lin(t, at, at + 0.2) : 0;
  return f > 0 ? <AbsoluteFill style={{ background: WHITE, opacity: f * 0.55 }} /> : null;
};

// ───────── peças ─────────
// sirene/alerta: anel que pulsa uma vez na entrada
const Alert: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const s = sp(t, at, 10, 240);
  const r = lin(t, at, at + 0.8);
  return (
    <div style={{ position: "relative", width: 200, height: 200, transform: `scale(${s})` }}>
      <div style={{ position: "absolute", inset: 0, borderRadius: 100, border: `10px solid ${AMBER}`, transform: `scale(${1 + r * 0.6})`, opacity: 1 - r }} />
      <div style={{ position: "absolute", inset: 0, borderRadius: 100, background: RED, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 20px 50px rgba(0,0,0,0.4)" }}>
        <span style={{ fontFamily: F, fontWeight: 700, fontSize: 150, color: WHITE, marginTop: -8 }}>!</span>
      </div>
    </div>
  );
};

// cartão com a apostila real (vídeo 1, primeiros segundos)
const Apostila: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const s = sp(t, a + 0.1, 15, 160);
  return (
    <div style={{ position: "absolute", left: 250, top: 600, width: 580, height: 840, borderRadius: 40, overflow: "hidden", boxShadow: "0 40px 90px rgba(60,30,0,0.35)", border: `10px solid ${WHITE}`,
      opacity: Math.min(1, s * 2), transform: `translateY(${(1 - s) * 900}px) rotate(${(1 - s) * -10 + 2 * lin(t, a, b) - 1}deg)` }}>
      <Clip t={t} src="video1" a={a} b={b} from={0.4} z0={1.12} z1={1.22} ox={50} oy={45} pos="50% 40%" />
    </div>
  );
};

// currículo: a linha nova entra marcada
const Curriculo: React.FC<{ t: number; at: number; mark: number }> = ({ t, at, mark }) => {
  const s = sp(t, at, 15, 170);
  const m = sp(t, mark, 11, 230);
  return (
    <div style={{ position: "absolute", left: 170, top: 520, width: 740, height: 900, borderRadius: 36, background: WHITE, boxShadow: "0 36px 90px rgba(60,30,0,0.28)", padding: "64px 64px", boxSizing: "border-box",
      transform: `translateY(${(1 - s) * 700}px) rotate(${(1 - s) * 8 - 1.5}deg)`, opacity: Math.min(1, s * 2) }}>
      <div style={{ display: "flex", alignItems: "center", gap: 34 }}>
        <div style={{ width: 150, height: 150, borderRadius: 75, background: "#EFE7DC", overflow: "hidden", position: "relative" }}>
          <div style={{ position: "absolute", left: 45, top: 26, width: 60, height: 60, borderRadius: 30, background: "#CDBEAA" }} />
          <div style={{ position: "absolute", left: 20, top: 96, width: 110, height: 90, borderRadius: 55, background: "#CDBEAA" }} />
        </div>
        <div>
          <div style={{ fontFamily: F, fontWeight: 700, fontSize: 64, color: INK, letterSpacing: "0.04em" }}>CURRÍCULO</div>
          <div style={{ marginTop: 16, width: 260, height: 16, borderRadius: 8, background: "#EAE2D7" }} />
        </div>
      </div>
      {[380, 300, 420, 260].map((w, i) => <div key={i} style={{ marginTop: i ? 26 : 70, width: w, height: 18, borderRadius: 9, background: "#EAE2D7" }} />)}
      <div style={{ marginTop: 70, display: "flex", alignItems: "center", gap: 26, padding: "28px 30px", borderRadius: 26, background: "#FFF1E4", border: `5px solid ${ORANGE}`,
        opacity: Math.min(1, m * 3), transform: `scale(${0.5 + 0.5 * m})` }}>
        <Check t={t} at={mark + 0.12} size={86} bg={GREEN} />
        <div style={{ fontFamily: F, fontWeight: 700, fontSize: 46, lineHeight: 1.1, color: ORANGE }}>Informática<br />Administrativa</div>
      </div>
    </div>
  );
};

const Check: React.FC<{ t: number; at: number; size?: number; bg?: string }> = ({ t, at, size = 64, bg = GREEN }) => {
  const s = sp(t, at, 11, 240);
  const d = k(t, at + 0.08, 0.28);
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ flex: "none", transform: `scale(${s})` }}>
      <circle cx={50} cy={50} r={48} fill={bg} />
      <path d="M28 52 L44 67 L73 35" fill="none" stroke={WHITE} strokeWidth={11} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={70} strokeDashoffset={70 * (1 - d)} />
    </svg>
  );
};

// etiqueta de preço R$ 99,90 (conta de 0 até 99,90)
const Price: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const s = sp(t, at, 11, 220);
  const v = 99.9 * k(t, at, 0.75);
  const [int, dec] = v.toFixed(2).split(".");
  const shine = lin(t, at + 0.9, at + 1.5);
  return (
    <div style={{ position: "relative", overflow: "hidden", padding: "26px 60px 34px", borderRadius: 48, background: WHITE, boxShadow: "0 34px 90px rgba(90,30,0,0.45)",
      opacity: Math.min(1, s * 3), transform: `scale(${0.4 + 0.6 * s}) rotate(${(1 - s) * 10 - 2}deg)`, display: "flex", alignItems: "flex-start" }}>
      <span style={{ fontFamily: F, fontWeight: 700, fontSize: 90, color: GREEN, marginTop: 30, marginRight: 14 }}>R$</span>
      <span style={{ display: "inline-block", minWidth: 290, textAlign: "right", fontFamily: F, fontWeight: 700, fontSize: 250, lineHeight: 1, color: ORANGE, letterSpacing: "-0.04em", fontVariantNumeric: "tabular-nums" }}>{int}</span>
      <span style={{ fontFamily: F, fontWeight: 700, fontSize: 110, color: ORANGE, marginTop: 22, fontVariantNumeric: "tabular-nums" }}>,{dec}</span>
      {shine > 0 && shine < 1 && <div style={{ position: "absolute", top: -40, bottom: -40, width: 140, left: `${-20 + 140 * shine}%`, background: "linear-gradient(90deg, rgba(255,210,150,0), rgba(255,210,150,0.6), rgba(255,210,150,0))", transform: "skewX(-20deg)" }} />}
    </div>
  );
};

const WaIcon: React.FC<{ size: number; color?: string; bg?: string }> = ({ size, color = WHITE, bg = WA }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={{ flex: "none" }}>
    <circle cx={50} cy={50} r={50} fill={bg} />
    <path d="M50 20 a30 30 0 0 0 -26 45 l-4 15 15 -4 a30 30 0 1 0 15 -56 z" fill="none" stroke={color} strokeWidth={6} strokeLinejoin="round" />
    <path d="M39 37 c-2 4 0 11 6 17 s13 8 17 6 l2 -5 -7 -4 -3 3 c-3 -1 -7 -5 -8 -8 l3 -3 -4 -7 z" fill={color} />
  </svg>
);
const PhoneIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={{ flex: "none" }}>
    <circle cx={50} cy={50} r={50} fill={ORANGE} />
    <path d="M36 26 l9 14 -6 6 c3 7 8 12 15 15 l6 -6 14 9 -4 9 c-20 2 -42 -20 -40 -40 z" fill={WHITE} />
  </svg>
);

// linha de contato da tela final
const Contact: React.FC<{ t: number; at: number; icon: React.ReactNode; label: string; num: string; accent: string }> = ({ t, at, icon, label, num, accent }) => {
  const s = sp(t, at, 15, 190);
  return (
    <div style={{ width: 840, display: "flex", alignItems: "center", gap: 34, padding: "30px 40px", borderRadius: 34, background: WHITE, border: `5px solid ${accent}`, boxShadow: "0 22px 60px rgba(60,30,0,0.16)", boxSizing: "border-box",
      opacity: Math.min(1, s * 3), transform: `translateX(${(1 - s) * 260}px)` }}>
      {icon}
      <div>
        <div style={{ fontFamily: F, fontWeight: 500, fontSize: 40, color: accent, letterSpacing: "0.03em" }}>{label}</div>
        <div style={{ fontFamily: F, fontWeight: 700, fontSize: 82, lineHeight: 1.05, color: INK, whiteSpace: "nowrap", letterSpacing: "-0.01em" }}>{num}</div>
      </div>
    </div>
  );
};

export const Multifuncoes: React.FC = () => {
  const frame = useCurrentFrame();
  const t = frame / MF_FPS - LEAD;
  return (
    <AbsoluteFill style={{ background: INK }}>
      {/* 1 · Atenção, Anápolis e região! três cortes secos nas aulas */}
      <Scene t={t} a={-0.2} b={0.72} tr="none" cam={[1.0, 1.04]}>
        <Clip t={t} src="video1" a={-0.2} b={0.72} from={5.2} z0={1.25} z1={1.15} ox={45} oy={45} />
      </Scene>
      <Scene t={t} a={0.72} b={1.3} tr="cut" cam={[1.06, 1.0]}>
        <Clip t={t} src="video3" a={0.72} b={1.3} from={14.6} z0={1.1} z1={1.2} ox={40} oy={55} />
      </Scene>
      <Scene t={t} a={1.3} b={2.0} tr="cut" cam={[1.0, 1.05]}>
        <Clip t={t} src="video2" a={1.3} b={2.0} from={12.1} z0={1.15} z1={1.08} ox={50} oy={60} />
      </Scene>
      {t < 2.15 && (
        <>
          <Scrim mid />
          <Flash t={t} at={0.72} />
          <Flash t={t} at={1.3} />
          <div style={{ position: "absolute", left: 120, right: 120, top: 560, display: "flex", flexDirection: "column", alignItems: "center", gap: 30, opacity: 1 - k(t, 2.0, 0.12) }}>
            <Alert t={t} at={0.05} />
            <Big t={t} at={0.09} size={150} shadow>ATENÇÃO,</Big>
            <Tag t={t} at={0.69} size={92}>ANÁPOLIS</Tag>
            <Big t={t} at={1.17} size={84} color={AMBER} shadow>e região!</Big>
          </div>
        </>
      )}

      {/* 2 · oportunidade de aprender informática: aulas reais */}
      <Scene t={t} a={2.0} b={4.4} tr="band" cam={[1, 1.06]}>
        <Clip t={t} src="video2" a={2.0} b={4.4} from={6.2} z0={1.3} z1={1.12} ox={55} oy={35} />
        <Scrim />
        <Block t={t} top={1260} at={2.03} gap={8}>
          <Words t={t} shadow size={62} words={[["Chegou", 2.03], ["a", 2.35], ["sua", 2.55]]} />
          <Big t={t} at={2.73} size={120} color={AMBER} shadow>oportunidade</Big>
        </Block>
      </Scene>
      <Scene t={t} a={4.4} b={6.75} tr="slideL" cam={[1.04, 1.0]} drift={30}>
        <Clip t={t} src="video3" a={4.4} b={6.75} from={4.0} z0={1.1} z1={1.24} ox={40} oy={60} />
        <Scrim top />
        <Block t={t} top={200} at={4.45} gap={8}>
          <Words t={t} shadow size={60} words={[["de", 4.45], ["se", 4.7], ["preparar", 4.86], ["para", 5.38], ["o", 5.48]]} />
          <Big t={t} at={5.52} size={112} shadow>mercado de</Big>
          <Tag t={t} at={6.02} bg={GREEN} size={100}>trabalho</Tag>
        </Block>
      </Scene>

      {/* 3 · matrículas abertas: apostila real em cartão, fundo claro */}
      <Scene t={t} a={6.75} b={12.15} tr="circle" cam={[1, 1.12]} drift={-70}>
        <Paper />
        <Block t={t} top={190} at={6.88} gap={14}>
          <Words t={t} size={60} color={INK} words={[["Estão", 6.88], ["abertas", 7.14], ["as", 7.58]]} />
          <Tag t={t} at={7.7} size={104}>MATRÍCULAS</Tag>
        </Block>
        <Apostila t={t} a={8.2} b={12.6} />
        <Block t={t} top={1520} at={8.42} out={10.7} gap={4}>
          <Words t={t} size={56} color={INK} words={[["Curso", 8.42], ["Completo", 8.76], ["de", 9.34]]} />
          <Big t={t} at={9.44} size={84} color={GREEN}>Informática</Big>
        </Block>
        <Block t={t} top={1520} at={10.82} gap={4}>
          <Big t={t} at={10.82} size={84} color={GREEN}>Administrativa</Big>
          <div style={{ fontFamily: F, fontWeight: 700, fontSize: 60, color: ORANGE, opacity: k(t, 11.0, 0.3), transform: `translateY(${(1 - k(t, 11.0, 0.4)) * 30}px)` }}>
            MULT <span style={{ color: GREEN }}>Profissões</span>
          </div>
        </Block>
      </Scene>

      {/* 4 · 100% prático: mãos no teclado */}
      <Scene t={t} a={12.15} b={14.25} tr="zoom" cam={[1, 1]}>
        <Clip t={t} src="video3" a={12.15} b={14.25} from={16.3} z0={1.35} z1={1.12} ox={50} oy={65} />
        <Scrim mid />
        <Block t={t} top={640} at={12.24} gap={18}>
          <Words t={t} shadow size={64} words={[["Um", 12.24], ["curso", 12.38]]} />
          <Big t={t} at={13.26} size={260} color={WHITE} shadow>100%</Big>
          <Tag t={t} at={13.58} size={112} bg={GREEN}>PRÁTICO</Tag>
        </Block>
      </Scene>

      {/* 5 · aprende fazendo: professor com a aluna */}
      <Scene t={t} a={14.25} b={16.0} tr="wipe" cam={[1, 1.05]}>
        <Clip t={t} src="video5" a={14.25} b={16.0} from={7.2} z0={1.2} z1={1.08} ox={50} oy={45} />
        <Scrim />
        <Block t={t} top={1300} at={14.34} gap={6}>
          <Words t={t} shadow size={62} words={[["Você", 14.34], ["aprende", 14.56]]} />
          <Big t={t} at={14.93} size={124} color={AMBER} shadow>fazendo</Big>
        </Block>
      </Scene>

      {/* 5b · habilidades no currículo (desenhado) */}
      <Scene t={t} a={16.0} b={18.5} tr="slideUp" cam={[1, 1.05]}>
        <Paper />
        <Block t={t} top={200} at={15.96} gap={6}>
